package com.enterprise.procurement.persistence.entity;
import com.baomidou.mybatisplus.annotation.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@TableName("purchase_request") public class PurchaseRequestEntity { @TableId(type=IdType.AUTO) private Long id; private String requestNo; private Long applicantId; private Long departmentId; private String reason; private BigDecimal totalAmount; private String status; private Integer version; private LocalDateTime createdAt; private LocalDateTime updatedAt;
 public Long getId(){return id;} public void setId(Long v){id=v;} public String getRequestNo(){return requestNo;} public void setRequestNo(String v){requestNo=v;} public Long getApplicantId(){return applicantId;} public void setApplicantId(Long v){applicantId=v;} public Long getDepartmentId(){return departmentId;} public void setDepartmentId(Long v){departmentId=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Integer getVersion(){return version;} public void setVersion(Integer v){version=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
